<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';
import { request,watchJob,errorText,terminal,date } from '../api';import { newer } from '../sse';import { coalesceAsync } from '../workflow';import type { Job,JobEvent,Page } from '../types';
const page=ref<Page<Job>>({items:[],nextPageToken:''});const cursor=ref('');const history=ref<string[]>([]);const busy=ref(false);const error=ref('');const selected=ref<Job>();const events=ref<JobEvent[]>([]);const streamState=ref('');const query=ref('');const route=useRoute();const router=useRouter();let active=new AbortController();let stream=new AbortController();let disposed=false;
async function load(){active.abort();active=new AbortController();const signal=active.signal;busy.value=true;error.value='';try{page.value=await request<Page<Job>>(`/jobs?pageSize=50&pageToken=${encodeURIComponent(cursor.value)}`,{signal});}catch(e){if(!signal.aborted)error.value=errorText(e);}finally{if(!signal.aborted)busy.value=false;}}
async function open(id:string){stream.abort();stream=new AbortController();const signal=stream.signal;query.value=id;selected.value=undefined;events.value=[];error.value='';streamState.value='读取任务';let sequence='0';
 const refresh=coalesceAsync(async()=>{try{const snapshot=await request<Job>(`/jobs/${encodeURIComponent(id)}`,{signal});if(!signal.aborted&&(!selected.value||!newer(selected.value.sequence,snapshot.sequence))){selected.value=snapshot;sequence=snapshot.sequence;events.value=snapshot.events.slice(-500);}}catch(e){if(!signal.aborted)streamState.value=`详情刷新失败：${errorText(e)}`;}});
 try{const job=await request<Job>(`/jobs/${encodeURIComponent(id)}`,{signal});if(signal.aborted)return;selected.value=job;events.value=job.events||[];sequence=job.sequence;while(!signal.aborted&&!disposed&&!terminal(selected.value.state)){streamState.value='订阅执行事件';try{await watchJob(id,sequence,signal,(event)=>{if(!newer(event.sequence,sequence))return;sequence=event.sequence;events.value.push(event);if(events.value.length>500)events.value.shift();if(selected.value){selected.value.sequence=event.sequence;if(!event.nodeId)selected.value.state=event.state;}refresh.trigger();});}catch(e){if(signal.aborted)return;streamState.value=`订阅中断：${errorText(e)}，将重连`;}
 if(signal.aborted)return;try{selected.value=await request<Job>(`/jobs/${encodeURIComponent(id)}`,{signal});sequence=selected.value.sequence;events.value=selected.value.events.slice(-500);}catch(e){streamState.value=`查询失败：${errorText(e)}`;}
 if(selected.value&&terminal(selected.value.state))break;await new Promise<void>((resolve)=>{const t=setTimeout(resolve,2000);signal.addEventListener('abort',()=>{clearTimeout(t);resolve();},{once:true});});}
 if(!signal.aborted)streamState.value='任务已结束';
 }catch(e){if(!signal.aborted){error.value=errorText(e);streamState.value='查询失败';}}finally{refresh.stop();}
}
function select(id:string){void router.replace({path:'/jobs',query:{id}});}function next(){history.value.push(cursor.value);cursor.value=page.value.nextPageToken;void load();}function previous(){cursor.value=history.value.pop()||'';void load();}
watch(()=>route.query.id,(id)=>{if(id)void open(String(id));});onMounted(()=>{void load();if(route.query.id)void open(String(route.query.id));});onBeforeUnmount(()=>{disposed=true;active.abort();stream.abort();});
</script>
<template><section class="sdn-page"><div class="page-head"><div><h1>任务中心</h1><p class="subtitle">配置提交后的持久化任务，包含各节点执行状态和错误。</p></div><el-button :loading="busy" @click="load">刷新任务</el-button></div><el-alert v-if="error" type="error" :title="error" :closable="false"/><div class="panel"><div class="toolbar"><el-input v-model="query" placeholder="输入 job_id 查询任务" aria-label="任务 ID" style="max-width:430px"/><el-button :disabled="!query" @click="select(query)">查询任务</el-button></div><el-table v-loading="busy" :data="page.items" empty-text="尚无配置任务"><el-table-column label="任务 ID" min-width="230"><template #default="{row}"><el-button link type="primary" @click="select(row.id)">{{row.id}}</el-button></template></el-table-column><el-table-column label="状态" width="180"><template #default="{row}"><el-tag :type="row.state==='SUCCEEDED'?'success':terminal(row.state)?'danger':'warning'">{{row.state}}</el-tag></template></el-table-column><el-table-column prop="desiredRevision" label="目标版本" width="100"/><el-table-column label="创建时间" min-width="170"><template #default="{row}">{{date(row.createdUnixMs)}}</template></el-table-column></el-table><div class="pagination"><el-button :disabled="!history.length||busy" @click="previous">上一页</el-button><span class="muted">第 {{history.length+1}} 页</span><el-button :disabled="!page.nextPageToken||busy" @click="next">下一页</el-button></div></div><div v-if="selected" class="panel"><h2>任务详情 · {{selected.state}}</h2><p class="mono">{{selected.id}}</p><p class="subtitle">{{streamState}} · 已处理事件 {{selected.sequence}}。配置成功与 BGP 收敛、业务连通性分别验证。</p><el-alert v-if="selected.error" type="error" :title="selected.error" :closable="false"/><el-table :data="selected.nodes"><el-table-column prop="nodeId" label="节点 ID" min-width="220"/><el-table-column prop="state" label="状态" width="160"/><el-table-column prop="agentRevision" label="Agent 版本" width="120"/><el-table-column prop="error" label="错误" min-width="200"/></el-table><h2 style="margin-top:24px">事件记录（最近 500 条）</h2><ul class="event-list"><li v-for="event in events" :key="event.sequence"><span class="mono muted">#{{event.sequence}} · {{date(event.timeUnixMs)}}</span><div>{{event.state}} · {{event.message}} <span class="mono">{{event.nodeId}}</span></div></li></ul></div></section></template>
